var total = ReadInt("Warehouse.Inventory.TotalLocations");
var occupied = ReadInt("Warehouse.Inventory.OccupiedLocations");
if (total > 0) {
    var util = (double)occupied / total * 100;
    Write("Warehouse.Inventory.Utilization_Pct", Math.Round(util, 1));
}

// Log conveyor motor current for predictive maintenance
var inboundCurrent = ReadDouble("Warehouse.Conveyors.InboundLine.MotorCurrent_A");
if (inboundCurrent > 12.0) {
    Log($"WARNING: Inbound conveyor motor current elevated: {inboundCurrent:F1}A - schedule maintenance");
}
